// Retrieve the session messages returned by Supabase
const messages = Array.isArray($json) ? $json : [$json];
const session_id = $('Webhook').first().json.body.session_id;

if (!messages || messages.length === 0) {
  throw new Error(`No messages found for session_id: ${session_id}`);
}

// ── Build readable conversation transcript ────────────────────────────────────
const transcript = messages
  .map(msg => {
    const roleLabel = msg.role === 'user' ? 'CLINIC OWNER' : 'AI COACH';
    const timestamp = msg.created_at
      ? new Date(msg.created_at).toLocaleTimeString('en-AU', { hour: '2-digit', minute: '2-digit' })
      : '';
    const timeStr = timestamp ? ` [${timestamp}]` : '';
    return `${roleLabel}${timeStr}:\n${msg.content}`;
  })
  .join('\n\n---\n\n');

const messageCount = messages.length;
const userMessageCount = messages.filter(m => m.role === 'user').length;
const coachMessageCount = messages.filter(m => m.role === 'assistant').length;

// ── Assemble the summary prompt ───────────────────────────────────────────────
const summary_prompt = `You are an expert AI business coach summarising a coaching session for a beauty/wellness clinic owner.

SESSION METADATA:
- Session ID: ${session_id}
- Total exchanges: ${messageCount} messages (${userMessageCount} from clinic owner, ${coachMessageCount} from coach)

CONVERSATION TRANSCRIPT:
${transcript}

Please produce a structured session summary with EXACTLY these three sections:

## 1. Session Summary
Write 3-4 sentences capturing: the main topic(s) discussed, the key business challenges raised, and the overall direction of the coaching conversation.

## 2. Key Insights
Provide bullet points covering:
- Data highlights or metrics mentioned (revenue, rebook rate, satisfaction scores, etc.)
- Root causes or patterns identified during the session
- Strengths observed in the business
- Risks or gaps that need attention

## 3. Action Plan for Next 7 Days
Provide a numbered priority list (at least 3, no more than 7 actions) of specific, concrete steps the clinic owner should take this week. Each action should:
- Start with a strong action verb
- Be achievable within 7 days
- Reference specific insights from this session where possible

Keep the summary professional, encouraging, and focused on tangible outcomes.`;

return [{
  json: {
    session_id,
    messages_formatted: transcript,
    summary_prompt,
    message_count: messageCount
  }
}];

// Extract DeepSeek summary text and pass along session metadata
const deepseekResponse = $json;
const buildData = $('Build Summary Prompt').first().json;

const ai_response = deepseekResponse?.choices?.[0]?.message?.content || 'No summary generated.';
const session_id = buildData.session_id;
const message_count = buildData.message_count;

return [{
  json: {
    ai_response,
    session_id,
    message_count
  }
}];
